}

int main() {
    std::vector<int> packets = {4, 7, 16, 25, 64, 100};
    for (int p : packets) {
        if (isPowerOfTwo(p)) {
            std::cout << p << " POWER_OF_2\n";
        } else {
            std::cout << p << " ODD_PACKET\n";
        }
    }
    return 0;
}

