#include <string>

void reverseEcho(const std::string& str, int index) {
    if (index < 0) return;
    std::cout << str[index];
    reverseEcho(str, index - 1);
}

int main() {
    std::string word = "NEXUS";
    reverseEcho(word, word.length() - 1);
    std::cout << std::endl;
