tasks.solutionSample:
#include <iostream>

int main() {
    int sectors[] = {12, 24, 36, 48, 60};
    int n = 5;
    int sum = 0;

    int* ptr = sectors;
    for (int i = 0; i < n; ++i) {
        sum += *ptr;
        ptr++;
    }

    std::cout << "SUM: " << sum << "\n";
    return 0;
}

